import{_ as a,C as d,o as r,c as o,E as s,a3 as n}from"./chunks/framework.C0R2UdF3.js";const i="/versions/v0.19.70/screens/devices/looper.png",y=JSON.parse('{"title":"Looper","description":"","frontmatter":{"title":"Looper","pageClass":"device-doc"},"headers":[],"relativePath":"devices/looper.md","filePath":"devices/looper.md"}'),h={name:"devices/looper.md"};function l(c,t,p,g,b,u){const e=d("DeviceHeading");return r(),o("div",null,[s(e,{slug:"looper",title:"Looper"}),t[0]||(t[0]=n('<p>Loop and overdub MIDI</p><p><img src="'+i+'" alt="Looper parameters" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Use <strong>Looper</strong> to <strong>record, overdub, and replay</strong> a MIDI phrase inside the rack.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Looper needs a <strong>Clock</strong> in the same rack. Without one, Record switches back off, nothing is recorded, and nothing plays.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Bypass</td><td>0 – 1</td><td>When on, the device is disabled and MIDI passes through unchanged.</td></tr><tr><td>Record</td><td>0 – 1</td><td>Arms a take that starts on the bar after the count-in. Pressing it during a take stops recording and plays what was captured. It does nothing in STOP mode.</td></tr><tr><td>Reset</td><td>0 – 1</td><td>Clears the loop buffer (momentary action).</td></tr><tr><td>Mode</td><td>0 – 2</td><td>Looper mode: STOP, ONCE, or OVERDUB.</td></tr><tr><td>Quantize</td><td>0 – 8</td><td>Snaps the start of each recorded note to the nearest grid step. Notes that snap onto the same step are merged.</td></tr><tr><td>Length</td><td>1 – 16</td><td>Loop length in bars (1–16).</td></tr><tr><td>Countdown</td><td>1 – 4</td><td>1 BAR starts the take on the next bar line. Each extra bar waits one more full bar.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="bypass" tabindex="-1">Bypass <a class="header-anchor" href="#bypass" aria-label="Permalink to &quot;Bypass&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>Off</td><td>Device is active and processes MIDI.</td></tr><tr><td style="text-align:right;">1</td><td>On</td><td>Device is bypassed; messages pass through unchanged.</td></tr></tbody></table><h3 id="mode" tabindex="-1">Mode <a class="header-anchor" href="#mode" aria-label="Permalink to &quot;Mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>STOP</td><td>Nothing records or plays. The loop is kept; switching to STOP during a take keeps what was recorded.</td></tr><tr><td style="text-align:right;">1</td><td>ONCE</td><td>Record starts a new take on the bar after the count-in: the old loop is cleared, Length bars are recorded, then the loop plays.</td></tr><tr><td style="text-align:right;">2</td><td>OVERDUB</td><td>Record adds notes on top of the loop on every pass, starting on the bar after the count-in, until you press Record again.</td></tr></tbody></table><h3 id="quantize" tabindex="-1">Quantize <a class="header-anchor" href="#quantize" aria-label="Permalink to &quot;Quantize&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>OFF</td><td>Notes are recorded where they were played.</td></tr><tr><td style="text-align:right;">1</td><td>1/4</td><td>Snaps recorded note starts to quarter notes.</td></tr><tr><td style="text-align:right;">2</td><td>1/8</td><td>Snaps recorded note starts to eighth notes.</td></tr><tr><td style="text-align:right;">3</td><td>1/8T</td><td>Snaps recorded note starts to eighth-note triplets.</td></tr><tr><td style="text-align:right;">4</td><td>1/8+1/8T</td><td>Snaps recorded note starts to a mixed eighth and triplet grid.</td></tr><tr><td style="text-align:right;">5</td><td>1/16</td><td>Snaps recorded note starts to sixteenth notes.</td></tr><tr><td style="text-align:right;">6</td><td>1/16T</td><td>Snaps recorded note starts to sixteenth-note triplets.</td></tr><tr><td style="text-align:right;">7</td><td>1/16+1/16T</td><td>Snaps recorded note starts to a mixed sixteenth and triplet grid.</td></tr><tr><td style="text-align:right;">8</td><td>1/32</td><td>Snaps recorded note starts to thirty-second notes.</td></tr></tbody></table><h3 id="countdown" tabindex="-1">Countdown <a class="header-anchor" href="#countdown" aria-label="Permalink to &quot;Countdown&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">Value</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>1 bar</td><td>One bar count-in before record.</td></tr><tr><td style="text-align:right;">2</td><td>2 bars</td><td>Two bar count-in.</td></tr><tr><td style="text-align:right;">3</td><td>3 bars</td><td>Three bar count-in.</td></tr><tr><td style="text-align:right;">4</td><td>4 bars</td><td>Four bar count-in.</td></tr></tbody></table>',16))])}const x=a(h,[["render",l]]);export{y as __pageData,x as default};
